INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LLER6A', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what is the meaning of "economy"?', E'The poet Yuko Tsujimura is celebrated for the economy of her verse. Where contemporaries might devote an entire stanza to establishing a scene, Tsujimura condenses her imagery into two or three precisely chosen words, trusting the reader to complete the picture. Critics have compared the effect to ink-wash painting, in which a single brushstroke suggests an entire mountainside.', $lyceon_json$[{"key":"A","text":"frugality with money"},{"key":"B","text":"brevity of expression"},{"key":"C","text":"system of commerce"},{"key":"D","text":"avoidance of controversy"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes Tsujimura condensing imagery into two or three precisely chosen words rather than devoting an entire stanza, and compares her technique to a single brushstroke suggesting a whole mountainside. This context makes clear that "economy" refers to the efficient, restrained use of language, which is captured by "brevity of expression." "Frugality with money" applies a financial sense of the word that is irrelevant to poetic technique. "System of commerce" invokes the macroeconomic meaning of the word, which has no bearing on how a poet constructs verse. "Avoidance of controversy" introduces a concept of caution or diplomacy that the passage never suggests; the discussion is entirely about conciseness, not about steering clear of contentious topics.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2O8CLSI', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'While researching a topic, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OB579O', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Musicologist Priya Chandrasekaran has proposed that the widespread critical characterization of gamelan music as "cyclical" obscures a more fundamental structural principle. Drawing on transcriptions of 47 Central Javanese court pieces recorded between 1893 and 1927, Chandrasekaran demonstrates that while the colotomic framework—the pattern of punctuating gong strokes—does indeed recur, the melodic elaboration performed by the panerusan instruments rarely repeats verbatim across successive cycles. She argues that this constant melodic variation within a fixed temporal scaffolding constitutes a form of structured improvisation that resists the cyclical label. Chandrasekaran further contends that the cyclical characterization persists partly because early Western ethnomusicologists, trained in the analysis of European harmonic periodicity, defaulted to familiar categories when describing unfamiliar temporal structures, and subsequent scholars have inherited this framing without sufficiently interrogating it.', $lyceon_json$[{"key":"A","text":"Chandrasekaran argues that the cyclical label for gamelan misrepresents its structure, since melodic elaboration varies continuously within a recurring framework, and the label persists due to inherited Western analytical habits."},{"key":"B","text":"Chandrasekaran's research reveals that Central Javanese court gamelan underwent a significant and previously undocumented stylistic transformation between the late nineteenth and early twentieth centuries, gradually moving away from strict cyclical repetition toward greater improvisational freedom in both melodic and rhythmic dimensions."},{"key":"C","text":"Early Western ethnomusicologists accurately identified the cyclical nature of gamelan's colotomic framework but failed to appreciate the harmonic complexity of the panerusan instruments' melodic contributions to the overall musical texture."},{"key":"D","text":"Chandrasekaran uses transcriptions of 47 court pieces to establish a comprehensive taxonomy of Javanese colotomic patterns, systematically classifying them by the frequency, duration, and placement of gong strokes within each cycle."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Chandrasekaran''s two-part argument: first, that the cyclical label is inaccurate because melodic elaboration varies even as the colotomic framework recurs, and second, that the label persists because of inherited Western analytical categories. The option capturing both the structural argument and the historiographic claim accurately summarizes the main idea. The option about a stylistic transformation between the nineteenth and twentieth centuries fabricates a historical narrative the passage does not describe; Chandrasekaran uses the transcriptions to analyze structure, not to trace change over time. The option about early ethnomusicologists accurately identifying cyclical structure contradicts the passage, which argues that the cyclical characterization itself is a misrepresentation. The option about establishing a taxonomy of colotomic patterns misrepresents the purpose of the transcription analysis, which is to show melodic variation within cycles, not to classify gong patterns.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OEO0KS', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if true, would most directly weaken the researchers'' proposed explanation?', E'Neuroscientists at the University of Zurich have proposed that the well-documented phenomenon of "tip-of-the-tongue" states—in which a person is certain they know a word but cannot retrieve it—arises because the semantic and phonological retrieval systems operate on slightly different time courses. According to the researchers'' model, the semantic system activates the word''s meaning 60 to 90 milliseconds before the phonological system retrieves its sound form. Tip-of-the-tongue states occur, they argue, when an external or internal interruption during this narrow temporal gap disrupts phonological retrieval while leaving semantic activation intact. The researchers note that tip-of-the-tongue states are more frequent during multitasking, which they interpret as consistent with the interruption-based account.', $lyceon_json$[{"key":"A","text":"People who experience frequent tip-of-the-tongue states tend to score higher on standardized vocabulary assessments than people who rarely experience them, suggesting that larger lexicons increase retrieval competition."},{"key":"B","text":"Neuroimaging data show that semantic and phonological brain regions activate simultaneously, with no measurable lag, during both successful and unsuccessful retrieval."},{"key":"C","text":"Tip-of-the-tongue states are reported more frequently by adults over the age of 65 than by adults between 25 and 40, a pattern researchers attribute to age-related slowing of lexical access processes."},{"key":"D","text":"Participants in laboratory studies can often identify the first letter or the number of syllables of a word they cannot fully produce during a tip-of-the-tongue state, indicating partial phonological activation."}]$lyceon_json$::jsonb, 'B', NULL, E'The researchers'' explanation depends on a temporal gap between semantic and phonological activation. A neuroimaging finding that both systems activate simultaneously with no measurable lag would eliminate the temporal gap that the model requires, directly weakening the proposed explanation. The finding about frequent tip-of-the-tongue experiencers scoring higher on vocabulary assessments relates to vocabulary size rather than the timing mechanism the model describes. The finding about age-related frequency differences is consistent with many possible explanations and does not specifically address the temporal-gap hypothesis. The finding about partial phonological retrieval could be seen as partially consistent with the model rather than weakening it, since it shows phonological information is partially but not fully retrieved.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OUEXRW', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the primary purpose of the text?', E'In her 2019 monograph, the archaeologist Priya Chandrasekaran challenges the prevailing interpretation of the carved stone seals found at Mohenjo-daro, one of the largest settlements of the ancient Indus Valley civilization. Most scholars have treated the seals as markers of mercantile ownership, pointing to their frequent discovery in warehouse districts and trade depots. Chandrasekaran acknowledges this evidence but argues that it accounts for only a subset of the seals. She notes that more than a third of the recovered seals bear animal motifs with no apparent commercial function and were found in residential and ritual contexts far from any marketplace. Chandrasekaran proposes that these seals served a ceremonial role linked to kinship identity, a hypothesis that, if correct, would require a significant revision of current models of Indus Valley social organization.', $lyceon_json$[{"key":"A","text":"It surveys the full range of archaeological artifacts recovered from the major excavation sites of the Indus Valley civilization and evaluates their relative importance to ongoing scholarly debates in the field."},{"key":"B","text":"It describes a researcher's argument that the established interpretation of certain artifacts is incomplete and outlines the implications of her alternative."},{"key":"C","text":"It contrasts two equally supported hypotheses about Indus Valley trade networks and explains why neither has gained scholarly consensus."},{"key":"D","text":"It traces the discovery history of the Mohenjo-daro seals and credits Chandrasekaran with being the first scholar to study them systematically."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage introduces the prevailing mercantile interpretation of the seals, presents Chandrasekaran''s argument that this interpretation is incomplete because it cannot account for seals found in non-commercial contexts, and then outlines her alternative ceremonial-kinship hypothesis along with its broader implications for models of Indus Valley social organization. The choice describing a researcher''s argument that the established interpretation is incomplete and outlining the implications of her alternative accurately captures this purpose. The choice about surveying the full range of archaeological artifacts is wrong because the passage focuses exclusively on carved stone seals, not on all artifacts from the site. The choice about two equally supported hypotheses is incorrect because the passage presents the mercantile view as the prevailing interpretation and Chandrasekaran''s hypothesis as a challenge to it, not as equally weighted alternatives. The choice about tracing the discovery history is wrong because the passage does not discuss when or how the seals were found and does not claim Chandrasekaran was the first to study them.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q8XEA9', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what is the meaning of "sparse"?', E'The botanist Ingrid Halvorsen spent three summers cataloging plant life across the volcanic plateau of central Iceland. She found the vegetation sparse, with only scattered mosses and a handful of dwarf shrubs clinging to the basalt. Kilometers of bare rock separated one patch of green from the next, giving the landscape an austere, almost lunar quality.', $lyceon_json$[{"key":"A","text":"poisonous"},{"key":"B","text":"scanty"},{"key":"C","text":"artificial"},{"key":"D","text":"towering"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes only scattered mosses and a handful of dwarf shrubs separated by kilometers of bare rock, indicating that plant life was thin and limited in quantity. The word "scanty" captures this sense of being meager and insufficient in amount. "Poisonous" refers to toxicity, which has no connection to the quantity or distribution of vegetation described. "Artificial" means human-made or synthetic, which contradicts the description of naturally occurring mosses and shrubs. "Towering" means very tall, which directly contradicts the mention of dwarf shrubs and low-growing mosses.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QKBBSS', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Which choice best states a relationship between the two texts?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QKJYQX', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what is the meaning of "galvanized"?', E'When the municipal council announced plans to demolish the 1920s-era Rialto Theater and replace it with a parking structure, the decision galvanized residents who had previously shown little interest in local governance. Within forty-eight hours, a coalition of shopkeepers, retired teachers, and high-school students had organized a petition drive, packed a public hearing, and retained a preservation attorney to challenge the demolition permit.', $lyceon_json$[{"key":"A","text":"bewildered and disoriented"},{"key":"B","text":"divided into hostile factions"},{"key":"C","text":"mobilized"},{"key":"D","text":"pacified after prolonged disagreement"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage describes residents who had been indifferent suddenly organizing a petition drive, attending a hearing, and hiring an attorney, all within forty-eight hours. This rapid shift from apathy to coordinated action indicates that the demolition announcement spurred them into action, and "mobilized" captures this meaning of being roused to collective effort. "Bewildered and disoriented" implies confusion, but the residents acted with clear purpose and coordination. "Divided into hostile factions" suggests internal disagreement, which contradicts the description of a unified coalition. "Pacified after prolonged disagreement" means soothed or calmed, which is the opposite of being stirred to urgent protest.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2S2785X', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Based on the text, what can most reasonably be inferred about the relationship between caddisfly larval cases and stream conditions?', E'Aquatic ecologist Miriam Okoro studied caddisfly larvae in 23 streams across the Appalachian Plateau in West Virginia. Caddisfly larvae construct portable tubular cases from materials found on the streambed, and Okoro observed that larvae in streams with predominantly fine-grained sediment built cases almost exclusively from sand particles and small shell fragments, while larvae in streams with coarser substrates incorporated larger pebbles and bark pieces. Notably, when Okoro transplanted larvae from fine-sediment streams into coarse-sediment streams, the larvae dismantled their original cases within 48 hours and rebuilt them using locally available coarser materials.', $lyceon_json$[{"key":"A","text":"Case composition reflects local material availability and changes when larvae encounter different substrate conditions."},{"key":"B","text":"Caddisfly larvae in coarse-sediment streams are healthier and grow to larger body sizes than those in fine-sediment streams because the larger building materials provide better structural protection against aquatic predators."},{"key":"C","text":"Caddisfly larvae inherit a fixed genetic preference for specific case-building materials that remains stable regardless of the stream environment they inhabit throughout their larval development."},{"key":"D","text":"Streams with fine-grained sediment generally support larger and more stable populations of caddisfly larvae than streams with coarse substrates across the entire Appalachian Plateau region of West Virginia."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage shows that larvae used different materials in different stream types and, when transplanted, rebuilt cases from the new environment''s materials within 48 hours. This directly supports the inference that case composition reflects local material availability and can change with conditions. The inference about coarse-sediment larvae being healthier introduces a health comparison and a predator-protection function that the passage does not address. The inference about genetic preference for specific materials contradicts the transplant finding, which showed larvae switching materials when relocated. The inference about population size differences between stream types introduces a comparison the passage never makes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
