INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2T1BN1C', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Every summer, the cluster of ancient olive trees near the village of Kritsa in eastern Crete_______ hundreds of amateur botanists who travel from across Europe to study the grove''s unusually dense canopy structure.', $lyceon_json$[{"key":"A","text":"draw"},{"key":"B","text":"draws"},{"key":"C","text":"have drawn"},{"key":"D","text":"are drawing"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is "cluster," a singular noun. The intervening prepositional phrases "of ancient olive trees" and "near the village of Kritsa in eastern Crete" do not change the number of the subject. A singular subject requires a singular verb. The option "draws" correctly provides a third-person singular present-tense verb matching the habitual action indicated by "Every summer." The bare plural form "draw" does not agree with the singular subject. The plural present-perfect "have drawn" incorrectly treats "trees" as the subject and shifts to a tense inconsistent with the habitual framing. Similarly, "are drawing" uses the plural auxiliary "are," which fails to agree with the singular "cluster."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VHTU54', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Restoration ecologist Amara Osei has devoted nineteen years to rehabilitating degraded peatlands across western Ireland; her primary method_______ controlled rewetting of drained bogs, a technique that simultaneously sequesters carbon and revives habitats for rare invertebrate species.', $lyceon_json$[{"key":"A","text":"method: controlled"},{"key":"B","text":"method, controlled"},{"key":"C","text":"method; controlled"},{"key":"D","text":"method. Controlled"}]$lyceon_json$::jsonb, 'A', NULL, E'The phrase "her primary method" is a noun phrase that introduces a specification of what that method is. A colon correctly links a noun phrase to the element that defines or elaborates it. The option using a colon appropriately signals that what follows identifies the method. A comma after a noun phrase followed by a noun phrase ("controlled rewetting") produces an unclear, unpunctuated appositive-like construction without the grammatical scaffolding to support it, and a comma alone cannot introduce an explanatory elaboration after a headless noun phrase. A semicolon requires independent clauses on both sides, but "her primary method" lacks a verb and is therefore not an independent clause. A period would leave "Her primary method." as a sentence fragment.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VOXLVF', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Based on the text, what can most reasonably be inferred about the architects'' approach?', E'When the municipal government of Tromsø, Norway, commissioned a new public library in 2019, the architects chose to orient the building''s primary reading rooms toward the north rather than the south. In most Norwegian construction, south-facing windows are preferred to maximize exposure to scarce winter sunlight. The Tromsø architects, however, noted that the city''s latitude of 69 degrees north means it experiences continuous daylight from late May through late July, and they designed deep-set northern windows fitted with translucent insulating panels to diffuse this persistent ambient light evenly across reading surfaces.', $lyceon_json$[{"key":"A","text":"They believed that south-facing windows would make the library uncomfortably warm during the long winter months when heating systems are already running at full capacity throughout the building."},{"key":"B","text":"They followed a standard architectural practice that has been adopted for all major public buildings constructed above the Arctic Circle in northern Norway since the early 2000s."},{"key":"C","text":"They prioritized consistent, diffused natural lighting suited to Tromsø's extreme seasonal daylight over the conventional approach of maximizing direct sun."},{"key":"D","text":"They intended the northern orientation primarily as an aesthetic choice to provide library visitors with panoramic views of the surrounding fjord and mountain landscape from the reading rooms."}]$lyceon_json$::jsonb, 'C', NULL, E'The passage explains that the architects departed from the conventional south-facing orientation because Tromsø''s extreme latitude provides continuous summer daylight, and they designed north-facing windows with translucent panels to diffuse this light evenly. This indicates they prioritized consistent, diffused lighting suited to the city''s unusual daylight conditions. The inference about winter warmth misidentifies the season and concern at issue; the passage focuses on managing persistent summer light, not winter heat. The inference about standard Arctic Circle practice contradicts the passage, which describes the choice as a departure from conventional Norwegian practice. The inference about panoramic views introduces a motivation the passage never mentions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XJ1ZYG', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'While researching a topic, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XV828R', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Architectural historian Tomoko Ishida has documented how Brutalist civic buildings of the 1960s were designed to convey democratic openness through exposed concrete and unadorned public atriums. Many residents, however, came to perceive these same structures as forbidding and alienating. __________ Ishida argues that the gap between the architects'' egalitarian intentions and the public''s hostile reception reveals how a building''s symbolic meaning is not fixed by its designer but is continuously renegotiated by its users.', E'Architectural historian Tomoko Ishida has documented how Brutalist civic buildings of the 1960s were designed to convey democratic openness through exposed concrete and unadorned public atriums. Many residents, however, came to perceive these same structures as forbidding and alienating. __________ Ishida argues that the gap between the architects'' egalitarian intentions and the public''s hostile reception reveals how a building''s symbolic meaning is not fixed by its designer but is continuously renegotiated by its users.', $lyceon_json$[{"key":"A","text":"For example,"},{"key":"B","text":"On this basis,"},{"key":"C","text":"Meanwhile,"},{"key":"D","text":"In spite of this,"}]$lyceon_json$::jsonb, 'B', NULL, E'The first two sentences establish a tension: architects intended democratic openness, but residents perceived alienation. The third sentence draws a broader conclusion from that tension, arguing that symbolic meaning is renegotiated by users. "On this basis," correctly signals that Ishida''s argument is built upon the evidence presented in the preceding sentences. "For example," would mean the third sentence illustrates a claim already stated, but the third sentence introduces the interpretive conclusion rather than serving as an illustration. "Meanwhile," implies simultaneous but unrelated events, which does not capture the logical relationship between the evidence and the conclusion. "In spite of this," implies the conclusion contradicts the preceding information, but Ishida''s argument follows from the gap described, not against it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YASLA6', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes a difference in how the authors of the two texts characterize the role of mycorrhizal networks in forests?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZJIJZ4', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'The larvae of the painted lady butterfly (Vanessa cardui) feed almost exclusively on thistle plants during their first two weeks of development. __________ adult painted ladies drink nectar from a wide variety of flowering species, including lavender, aster, and zinnia.', E'The larvae of the painted lady butterfly (Vanessa cardui) feed almost exclusively on thistle plants during their first two weeks of development. __________ adult painted ladies drink nectar from a wide variety of flowering species, including lavender, aster, and zinnia.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"Consequently,"},{"key":"D","text":"For this reason,"}]$lyceon_json$::jsonb, 'B', NULL, E'The first sentence describes the larvae''s narrow diet (almost exclusively thistle), while the second sentence describes the adults'' broad diet (a wide variety of flowering species). "In contrast," correctly signals this shift from a restricted to a diverse feeding pattern. "Similarly," incorrectly implies the two sentences describe comparable behaviors, but the diets differ sharply. "Consequently," implies the adult diet results from the larval diet, which the passage does not support. "For this reason," also implies causation, suggesting the larval diet explains the adult diet, but no causal link is presented.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
